package com.uop.recordingtools.service;
import com.uop.recordingtools.storage.DataStore; import org.bukkit.entity.Player; import java.net.InetAddress; import java.util.*;
public final class ProtectionService{private final DataStore store;public ProtectionService(org.bukkit.plugin.java.JavaPlugin p,DataStore s){store=s;}private String b(String n){return "protection."+n.toLowerCase(Locale.ROOT);}public void add(Player p,String mode){String b=b(p.getName());store.set(b+".name",p.getName());store.set(b+".uuid",p.getUniqueId().toString());store.set(b+".ip",ip(p));store.set(b+".mode",mode.toLowerCase(Locale.ROOT));store.saveNow();}public void remove(Player p){store.remove(b(p.getName()));store.saveNow();}public Set<String> list(){var s=store.data().getConfigurationSection("protection");return s==null?Set.of():s.getKeys(false);}public void reset(){store.remove("protection");store.saveNow();}public boolean allowed(String name,UUID uuid,InetAddress addr){String b=b(name);if(!store.data().contains(b))return true;String mode=store.data().getString(b+".mode","both");boolean u=uuid.toString().equalsIgnoreCase(store.data().getString(b+".uuid",""));boolean i=Objects.equals(ip(addr),store.data().getString(b+".ip",""));return switch(mode){case "uuid"->u;case "ip"->i;default->u&&i;};}private String ip(Player p){return p.getAddress()==null?"":ip(p.getAddress().getAddress());}private String ip(InetAddress a){return a==null?"":a.getHostAddress();}}
